from dataclasses import dataclass


@dataclass
class Num:
    v: int


@dataclass
class Add:
    l: "Expr"
    r: "Expr"


@dataclass
class Mul:
    l: "Expr"
    r: "Expr"


Expr = Num | Add | Mul


def eval_expr(e: Expr) -> int:
    """Evaluate an expression tree of Num, Add, and Mul nodes to an int."""
    if isinstance(e, Num):
        return e.v
    if isinstance(e, Add):
        return eval_expr(e.l) + eval_expr(e.r)
    if isinstance(e, Mul):
        return eval_expr(e.l) * eval_expr(e.r)
    raise TypeError(f"unknown expression node: {e!r}")


def test_eval_num() -> None:
    assert eval_expr(Num(3)) == 3
    assert eval_expr(Num(-7)) == -7


def test_eval_add() -> None:
    assert eval_expr(Add(Num(2), Num(5))) == 7


def test_eval_mul() -> None:
    assert eval_expr(Mul(Num(4), Num(6))) == 24


def test_eval_nested() -> None:
    # 1 + (2 * 3) = 7
    assert eval_expr(Add(Num(1), Mul(Num(2), Num(3)))) == 7
    # (1 + 2) * (3 + 4) = 21
    assert eval_expr(Mul(Add(Num(1), Num(2)), Add(Num(3), Num(4)))) == 21


def test_eval_negative_and_zero() -> None:
    assert eval_expr(Mul(Num(0), Num(-5))) == 0
    assert eval_expr(Add(Num(-3), Num(-4))) == -7
